import Aurora from "@/components/aurora"
import { BubbleMenu } from "@/components/navigation/bubble-menu"
import { FlowingMenu } from "@/components/sections/flowing-menu"

const experiences = [
  {
    title: "Full Stack Development & AI Intern — Shiksak",
    slug: "shiksak-intern",
  },
  {
    title: "Social Media Intern — Citizen for Public Leadership (CPL)",
    slug: "cpl-intern",
  },
  {
    title: "AI/ML Intern — NIELIT",
    slug: "nielit-intern",
  },
]

export default function ExperiencePage() {
  return (
    <div className="relative min-h-screen">
      <Aurora
        colorStops={["#3A29FF", "#FF94B4", "#FF3232"]}
        blend={0.5}
        amplitude={1.0}
        speed={0.5}
      />

      <BubbleMenu />

      <div className="relative z-10">
        <div className="text-center pt-32 pb-16">
          <h1 className="font-heading text-6xl md:text-7xl font-bold text-white">Experience</h1>
        </div>

        <FlowingMenu items={experiences} basePath="/experience" />
      </div>
    </div>
  )
}
